var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var pick = function (c) { return root.querySelector('.t25-position-card-' + c); };
var elMark = pick('mark'), elVal = pick('val'), elPl = pick('pl'), elPlv = pick('plv'), elPlp = pick('plp');
var qty = 240, entry = 171.08, price = 184.62, shown = 0, raf = 0;
var money = function (n, d) {
  return n.toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
};
var paint = function (dir) {
  var pnl = (price - entry) * qty;
  var pct = (price / entry - 1) * 100;
  var up = pnl >= 0;
  elMark.textContent = money(price, 2);
  elVal.textContent = money(price * qty, 0);
  elPlp.textContent = (up ? '▲ ' : '▼ ') + money(Math.abs(pct), 2) + '%';
  elPl.classList.toggle('t25-position-card-up', up);
  elPl.classList.toggle('t25-position-card-down', !up);
  if (reduce) {
    shown = pnl;
    elPlv.textContent = (up ? '+' : '−') + money(Math.abs(pnl), 2);
    return;
  }
  if (dir) {
    elMark.classList.remove('t25-position-card-flash-up', 't25-position-card-flash-dn');
    void elMark.offsetWidth;
    elMark.classList.add(dir > 0 ? 't25-position-card-flash-up' : 't25-position-card-flash-dn');
  }
  var from = shown, t0 = 0;
  cancelAnimationFrame(raf);
  var step = function (t) {
    if (!t0) t0 = t;
    var k = Math.min(1, (t - t0) / 420);
    var v = from + (pnl - from) * (1 - Math.pow(1 - k, 3));
    elPlv.textContent = (v >= 0 ? '+' : '−') + money(Math.abs(v), 2);
    if (k < 1) raf = requestAnimationFrame(step); else shown = pnl;
  };
  raf = requestAnimationFrame(step);
};
paint(0);
if (!reduce) {
  var timer = setInterval(function () {
    if (!root.isConnected) { clearInterval(timer); return; }
    var d = Math.round((Math.random() - 0.44) * 90) / 100;
    if (d === 0) d = 0.03;
    price = Math.round((price + d) * 100) / 100;
    paint(d > 0 ? 1 : -1);
  }, 1900);
}

