var out = root.querySelector('.t25-profit-waterfall-readout');
var cols = root.querySelectorAll('.t25-profit-waterfall-col');
var base = out.innerHTML;
var enter = function (col) {
  root.classList.add('t25-profit-waterfall-dim');
  for (var j = 0; j < cols.length; j++) cols[j].classList.remove('t25-profit-waterfall-on');
  col.classList.add('t25-profit-waterfall-on');
  out.innerHTML = col.getAttribute('data-n') + ' ' + col.getAttribute('data-v');
  var cn = col.className;
  out.style.color = cn.indexOf('c-dn') > -1 ? '#ff5f6d' : (cn.indexOf('c-net') > -1 ? '#8fb4ff' : '#3ddc97');
};
var leave = function () {
  root.classList.remove('t25-profit-waterfall-dim');
  for (var j = 0; j < cols.length; j++) cols[j].classList.remove('t25-profit-waterfall-on');
  out.innerHTML = base;
  out.style.color = '';
};
var replay = function () {
  var parts = root.querySelectorAll('.t25-profit-waterfall-bar, .t25-profit-waterfall-val, .t25-profit-waterfall-link');
  for (var j = 0; j < parts.length; j++) {
    parts[j].style.animation = 'none';
    void parts[j].offsetWidth;
    parts[j].style.animation = '';
  }
};
for (var i = 0; i < cols.length; i++) {
  (function (col) {
    col.addEventListener('mouseenter', function () { enter(col); });
    col.addEventListener('focus', function () { enter(col); });
    col.addEventListener('mouseleave', leave);
    col.addEventListener('blur', leave);
    col.addEventListener('click', replay);
  })(cols[i]);
}

