var segs = root.querySelectorAll('.t25-exposure-bar-seg');
var hit = function (k) {
  root.classList.add('t25-exposure-bar-dim');
  for (var j = 0; j < segs.length; j++) {
    segs[j].classList.toggle('t25-exposure-bar-on', segs[j].getAttribute('data-k') === k);
  }
  for (var m = 0; m < rows.length; m++) {
    var on = rows[m].getAttribute('data-k') === k;
    rows[m].style.background = on ? 'rgba(255,255,255,.06)' : '';
    if (on) head.innerHTML = rows[m].getAttribute('data-r');
  }
};
var off = function () {
  root.classList.remove('t25-exposure-bar-dim');
  for (var j = 0; j < segs.length; j++) segs[j].classList.remove('t25-exposure-bar-on');
  for (var m = 0; m < rows.length; m++) rows[m].style.background = '';
  head.innerHTML = base;
};
for (var i = 0; i < rows.length; i++) {
  (function (el) {
    var k = el.getAttribute('data-k');
    el.addEventListener('mouseenter', function () { hit(k); });
    el.addEventListener('focus', function () { hit(k); });
    el.addEventListener('mouseleave', off);
    el.addEventListener('blur', off);
    el.addEventListener('click', function () { hit(k); });
  })(rows[i]);
}
for (var s = 0; s < segs.length; s++) {
  (function (el) {
    var k = el.getAttribute('data-k');
