var rpct = q('rpct'), rusd = q('rusd');
var shares = q('shares'), notional = q('notional'), risked = q('risked');
var ACCT = 25000;
var bump = function (el, txt) {
  if (el.textContent === txt) return;
  el.textContent = txt;
  if (reduce) return;
  el.classList.remove('t25-size-calc-bump');
  void el.offsetWidth;
  el.classList.add('t25-size-calc-bump');
};
var calc = function () {
  var p = parseFloat(rng.value);
  var e = parseFloat(entry.value);
  var s = parseFloat(stop.value);
  var budget = ACCT * p / 100;
