    bump(shares, '—');
    bump(notional, '—');
    bump(risked, '—');
    return;
  }
  note.textContent = 'Acct $25,000';
  var n = Math.floor(budget / per);
  bump(shares, n.toLocaleString('en-US'));
  bump(notional, '$' + Math.round(n * e).toLocaleString('en-US'));
  bump(risked, '▼ $' + Math.round(n * per).toLocaleString('en-US'));
};
