  background:linear-gradient(160deg,#151b28,#0d1119 72%);
  color:#e9eef7; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  font-variant-numeric:tabular-nums; display:flex; flex-direction:column; gap:6px;
}
.t25-breakeven-head{display:flex; align-items:center; gap:6px}
.t25-breakeven-tkr{font-size:12px; font-weight:700}
.t25-breakeven-side{font-size:8px; font-weight:700; letter-spacing:.08em; color:#c8d1e2; background:rgba(255,255,255,.08); padding:2px 5px; border-radius:4px}
.t25-breakeven-state{margin-left:auto; font-size:9px; font-weight:700; color:var(--t25-be-mk); letter-spacing:.03em}
.t25-breakeven-rail{
  position:relative; height:34px; border-radius:7px; background:#0a0e16;
  border:1px solid rgba(255,255,255,.07);
}
.t25-breakeven-loss{
  position:absolute; left:0; top:0; bottom:0; width:var(--t25-be); border-radius:6px 0 0 6px;
  background:linear-gradient(90deg,rgba(255,95,109,.26),rgba(255,95,109,.07));
}
.t25-breakeven-gain{
  position:absolute; left:var(--t25-be); right:0; top:0; bottom:0; border-radius:0 6px 6px 0;
  background:linear-gradient(90deg,rgba(61,220,151,.05),rgba(61,220,151,.24));
}
.t25-breakeven-entry{position:absolute; left:var(--t25-en); top:7px; bottom:7px; width:1px; background:rgba(255,255,255,.4)}
.t25-breakeven-entry::after{
  content:''; position:absolute; left:-2px; bottom:-3px; width:5px; height:5px;
  border-radius:50%; background:rgba(255,255,255,.55);
}
.t25-breakeven-be{
  position:absolute; left:var(--t25-be); top:0; bottom:0; width:0;
  border-left:1px dashed #ffc46b; animation:t25-breakeven-breathe 2.6s ease-in-out infinite;
}
.t25-breakeven-mark{
  position:absolute; left:var(--t25-mk); top:0; bottom:0; width:2px; margin-left:-1px;
  border-radius:1px; background:var(--t25-be-mk);
  box-shadow:0 0 10px 1px rgba(61,220,151,.4);
  transition:left .6s cubic-bezier(.22,1,.36,1), background .3s ease, box-shadow .3s ease;
}
.t25-breakeven-mklbl{
  position:absolute; left:50%; top:3px; transform:translateX(-50%);
  font-size:9.5px; font-weight:700; color:#06110c; background:var(--t25-be-mk);
  padding:1px 4px; border-radius:4px; white-space:nowrap;
  font-variant-numeric:tabular-nums; font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
}
.t25-breakeven-scale{position:relative; height:11px}
.t25-breakeven-lo{position:absolute; left:0; font-size:8.5px; color:var(--t25-be-mu)}
.t25-breakeven-hi{position:absolute; right:0; font-size:8.5px; color:var(--t25-be-mu)}
.t25-breakeven-belbl{
