.t25-breakeven-foot{display:grid; grid-template-columns:auto 1fr; gap:1px 8px; align-items:baseline}
.t25-breakeven-fk{font-size:8.5px; letter-spacing:.07em; text-transform:uppercase; color:var(--t25-be-mu)}
.t25-breakeven-fv{
  font-size:12px; font-weight:700; text-align:right; color:var(--t25-be-mk);
