.t25-breakeven-fs{grid-column:1 / span 2; font-size:8.5px; color:var(--t25-be-mu); font-variant-numeric:tabular-nums}
.t25-breakeven-below{--t25-be-mk:#ff5f6d}
.t25-breakeven-below .t25-breakeven-mark{box-shadow:0 0 10px 1px rgba(255,95,109,.4)}
.t25-breakeven-below .t25-breakeven-mklbl{color:#180507}
.t25-breakeven-blink{animation:t25-breakeven-blink .5s ease-out}
@keyframes t25-breakeven-breathe{0%,100%{opacity:.45} 50%{opacity:1}}
@keyframes t25-breakeven-blink{0%{opacity:.25} 100%{opacity:1}}
@media (prefers-reduced-motion:reduce){
  .t25-breakeven-be{animation:none; opacity:.8}
  .t25-breakeven-mark{transition:none}
  .t25-breakeven-blink{animation:none}
}

