var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var q = function (c) { return root.querySelector('.t25-breakeven-' + c); };
var mark = q('mark'), lbl = q('mklbl'), state = q('state'), fv = q('fv'), fs = q('fs');
var LO = 165, HI = 190, BE = 171.94, ENTRY = 171.08, QTY = 300;
var price = 184.62;
var place = function (p) { return Math.max(4, Math.min(94, (p - LO) / (HI - LO) * 100)); };
var paint = function (flash) {
  var d = price - BE, up = d >= 0;
  root.style.setProperty('--t25-mk', place(price).toFixed(1) + '%');
  root.classList.toggle('t25-breakeven-below', !up);
  lbl.textContent = price.toFixed(2);
  state.textContent = (up ? '▲ above' : '▼ below') + ' break-even';
  fv.textContent = (up ? '▲ +' : '▼ −') + Math.abs(d).toFixed(2) +
    ' (' + (up ? '+' : '−') + Math.abs(d / BE * 100).toFixed(2) + '%)';
  fs.textContent = 'entry ' + ENTRY.toFixed(2) + ' · fees 0.86 · unreal ' +
    ((price - ENTRY) >= 0 ? '+$' : '−$') +
    Math.abs(Math.round((price - ENTRY) * QTY)).toLocaleString('en-US');
  if (flash && !reduce) {
    fv.classList.remove('t25-breakeven-blink');
    void fv.offsetWidth;
    fv.classList.add('t25-breakeven-blink');
  }
};
if (reduce) {
  paint(false);
} else {
  root.style.setProperty('--t25-mk', '27.8%');
  requestAnimationFrame(function () { requestAnimationFrame(function () { paint(false); }); });
  var timer = setInterval(function () {
    if (!root.isConnected) { clearInterval(timer); return; }
    var step = Math.round((Math.random() - 0.47) * 160) / 100;
    price = Math.min(188.4, Math.max(168.2, Math.round((price + step) * 100) / 100));
    paint(true);
  }, 2200);
}
